	s2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	g, _ := s2.Get(j1.ID)
	if g.Status != StatusFailed || !strings.Contains(g.FailureReason, "中断") {
		t.Fatalf("graceful close recovery: status=%s reason=%q", g.Status, g.FailureReason)
	}
}

